+static void sort_radix_lsd(uint32_t* a, uint32_t* tmp, size_t n) {
+    constexpr int BITS = 16; // Will be swept
+    constexpr int RADIX = 1 << BITS;
+    constexpr int PASSES = 2; // Will be swept
+    constexpr size_t MASK = RADIX - 1;
+    constexpr int SHIFT = BITS;
+
+    std::vector<uint32_t> counts(RADIX, 0);
+    std::vector<size_t> pos(RADIX);
+
+    for (int p = 0; p < PASSES; ++p) {
+        // Reset counts and positions
+        if (n > 0) {
+            // Use NEON to zero out counts if possible, though std::fill is often optimized well.
+            // We will focus on optimizing the counting loop itself.
+            std::fill(counts.begin(), counts.end(), 0);
+        }
+        
+        // Optimized counting pass using NEON if available
+        if (n > 0) {
+            // Optimized counting pass using standard loop, relying on compiler auto-vectorization
+            for (size_t j = 0; j < n; ++j) {
+                counts[(a[j] >> (p * SHIFT)) & MASK]++;
+            }
+        }
+
+
+        // Calculate starting positions (cumulative sum)
+        size_t current_pos = 0;
+        for (int r = 0; r < RADIX; ++r) {
+            pos[r] = current_pos;
+            current_pos += counts[r];
+        }
+
+        // Stable sort using counting sort, ping-pong between a and tmp
+        for (size_t i = 0; i < n; ++i) {
+            int r = (a[i] >> (p * SHIFT)) & MASK;
+            tmp[pos[r]++] = a[i];
+        }
+        
+        // Swap roles: tmp becomes the source for the next pass, a becomes the destination
+        std::swap(a, tmp);
+    }
